floor_fn:
"""Determines whether a *line* looks like an HL7 message.
    This method only does a cursory check and does not fully
    validate the message.

    :rtype: bool
    """
def ishl7(line: Any) -> object {
    return line.strip().startswith('MSH') if line else False;
}

test_blocks:
test "t0" {
    assert (ishl7('MSH|^~\&|||||blah blah blah') == True);;
}

test "t1" {
    assert (
        ishl7(
            'MSH^~\&|ADT1|GOOD HEALTH HOSPITAL|GHH LAB, INC.|GOOD HEALTH HOSPITAL|198808181126|SECURITY|ADT^A01^ADT_A01|MSG00001|P|2.6'
        )
        == True
    );;
}

test "t2" {
    assert (
        ishl7(
            'MSH|^~\&|SENDING APP|SENDING FAC|RECEIVING APP|RECEIVING FAC|20161201134225||ADT^A01|0123456789012345|P|2.5||||AL\r'
        )
        == True
    );;
}

test "t3" {
    assert (ishl7('MSH|^~\&|||||') == True);;
}

test "t4" {
    assert (ishl7('     ') == False);;
}

test "t5" {
    assert (
        ishl7(
            'MSH|^~\&|SENDING APP|SENDING FAC|RECEIVING APP|RECEIVING FAC|20161201134225||ADT^A01|0123456789012345|P|2.5||||AL\r\n\r'
        )
        == True
    );;
}

test "t6" {
    assert (ishl7(b'') == False);;
}

test "t7" {
    assert (ishl7('') == False);;
}

test "t8" {
    assert (
        ishl7(
            r'MSH|^~\&|SENDING APP|SENDING FACILITY|REC APP|REC FACILITY|20170114123123||ADT^A01^ADT_A01|928922|P|2.5'
        )
        == True
    );;
}

test "t9" {
    assert (ishl7(None) == False);;
}

test "t10" {
    assert (
        ishl7(
            'MSH|^~\&|SENDING APP|SENDING FAC|RECEIVING APP|RECEIVING FAC|20161201134225||ADT^A01|0123456789012345|P|2.5||||AL\r\n'
        )
        == True
    );;
}

test "t11" {
    assert (
        ishl7(r'MSH|^~\&|GHH LAB,ELAB\|ELAB\|200202150930||ORU^R01|CNTRL-3456|P|2.4')
        == True
    );;
}

test "t12" {
    assert (
        ishl7(
            'MSH|^~\&|ADT1|GOOD HEALTH HOSPITAL|GHH LAB, INC.|GOOD HEALTH HOSPITAL|198808181126|SECURITY|ADT^A01^ADT_A01|MSG00001|P|2.6'
        )
        == True
    );;
}

test "t13" {
    assert (ishl7('MSH|^~\&') == True);;
}

test "t14" {
    assert (ishl7('abc') == False);;
}
